  `best_trade_pct` decimal(10,4) NOT NULL DEFAULT '0.0000',
  `worst_trade_pct` decimal(10,4) NOT NULL DEFAULT '0.0000',
  `max_drawdown_pct` decimal(10,4) NOT NULL DEFAULT '0.0000',
