CREATE TABLE `strategy_registry` (
  `id` int NOT NULL AUTO_INCREMENT,
  `strategy_id` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Unique strategy identifier (e.g. btc_ichimoku_cloud)',
  `strategy_name` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Human-readable name or description',
  `system_name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Parent system (alpha_engine, kimi, baby_strategies, etc.)',
  `section_name` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Section from ALL_STRATEGIES.md',
  `module_file` varchar(300) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Source file path',
  `asset_class` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT 'CRYPTO',
  `strategy_type` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Type/category (Mean Reversion, Trend, etc.)',
  `win_rate` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Documented WR (e.g. 65%, 60-70%)',
  `sharpe` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Documented Sharpe ratio',
  `source_ref` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Academic/research source',
  `is_banned` tinyint(1) NOT NULL DEFAULT '0' COMMENT '1 if strategy is in BANNED_STRATEGIES',
  `is_active` tinyint(1) NOT NULL DEFAULT '1' COMMENT '1 if strategy is currently active',
  `notes` text COLLATE utf8mb4_unicode_ci,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_strategy_system` (`strategy_id`,`system_name`),
  KEY `idx_system` (`system_name`),
  KEY `idx_asset_class` (`asset_class`),
  KEY `idx_banned` (`is_banned`)
) ENGINE=InnoDB AUTO_INCREMENT=7733 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

