  `variant_name` varchar(128) NOT NULL,
  `variant_type` varchar(32) NOT NULL,
  `params_json` text NOT NULL,
  `baseline_win_rate` decimal(8,4) DEFAULT NULL,
  `baseline_pf` decimal(10,4) DEFAULT NULL,
  `baseline_trades` int DEFAULT NULL,
  `variant_win_rate` decimal(8,4) DEFAULT NULL,
  `variant_pf` decimal(10,4) DEFAULT NULL,
  `variant_trades` int DEFAULT NULL,
  `delta_win_rate` decimal(8,4) DEFAULT NULL,
  `delta_pf` decimal(10,4) DEFAULT NULL,
  `delta_trades` int DEFAULT NULL,
  `accepted` tinyint(1) DEFAULT '0',
  `created_at` datetime NOT NULL,
  PRIMARY KEY (`whatif_id`),
  KEY `idx_whatif_strat` (`strategy_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `super_strategy_candidates` (
  `strategy_id` varchar(128) NOT NULL,
  `symbols_passed` int DEFAULT '0',
  `asset_classes_passed` int DEFAULT '0',
  `regimes_passed` int DEFAULT '0',
  `concentration_ratio` decimal(10,4) DEFAULT NULL,
  `fisher_p` decimal(12,8) DEFAULT NULL,
  `status` varchar(32) NOT NULL,
  `notes` text,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`strategy_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `test_portfolio_positions` (
  `portfolio_name` varchar(64) NOT NULL,
  `position_id` bigint NOT NULL AUTO_INCREMENT,
  `strategy_id` varchar(128) NOT NULL,
  `symbol` varchar(64) NOT NULL,
  `direction` varchar(8) NOT NULL,
  `entry_price` decimal(18,8) NOT NULL,
  `take_profit` decimal(18,8) NOT NULL,
  `stop_loss` decimal(18,8) NOT NULL,
  `status` varchar(16) NOT NULL,
  `opened_at` datetime NOT NULL,
  `closed_at` datetime DEFAULT NULL,
  `pnl_pct` decimal(10,4) DEFAULT NULL,
  `metadata_json` text,
  PRIMARY KEY (`position_id`),
  KEY `idx_portfolio_strat` (`strategy_id`),
  KEY `idx_portfolio_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `tracked_portfolio_picks` (
  `id` int NOT NULL AUTO_INCREMENT,
  `portfolio_id` int NOT NULL,
  `ticker` varchar(20) NOT NULL,
  `company_name` varchar(200) DEFAULT '',
  `algorithm` varchar(100) DEFAULT '',
  `entry_price` decimal(12,4) NOT NULL,
  `current_price` decimal(12,4) DEFAULT NULL,
  `take_profit` decimal(12,4) NOT NULL,
  `stop_loss` decimal(12,4) NOT NULL,
  `tp_pct` decimal(6,2) NOT NULL DEFAULT '10.00',
  `sl_pct` decimal(6,2) NOT NULL DEFAULT '5.00',
  `hold_days` int NOT NULL DEFAULT '7',
  `status` varchar(20) NOT NULL DEFAULT 'active',
  `current_return_pct` decimal(10,4) DEFAULT '0.0000',
  `peak_price` decimal(12,4) DEFAULT NULL,
  `trough_price` decimal(12,4) DEFAULT NULL,
  `exit_price` decimal(12,4) DEFAULT NULL,
  `exit_date` date DEFAULT NULL,
  `exit_reason` varchar(50) DEFAULT NULL,
  `entry_date` date NOT NULL,
  `days_held` int DEFAULT '0',
  `last_price_date` date DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_portfolio` (`portfolio_id`),
  KEY `idx_status` (`status`),
  KEY `idx_ticker` (`ticker`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;

CREATE TABLE `tracked_portfolios` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(200) NOT NULL,
  `strategy_type` varchar(50) NOT NULL DEFAULT 'custom',
  `category` varchar(20) NOT NULL DEFAULT 'swing',
  `initial_capital` decimal(12,2) NOT NULL DEFAULT '10000.00',
  `status` varchar(20) NOT NULL DEFAULT 'active',
  `total_picks` int NOT NULL DEFAULT '0',
  `tp_hits` int NOT NULL DEFAULT '0',
  `sl_hits` int NOT NULL DEFAULT '0',
  `active_picks` int NOT NULL DEFAULT '0',
  `total_return_pct` decimal(10,4) DEFAULT '0.0000',
  `best_pick` varchar(20) DEFAULT NULL,
  `worst_pick` varchar(20) DEFAULT NULL,
  `last_refreshed` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;

CREATE TABLE `trading_picks` (
  `id` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `symbol` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `direction` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `strategy` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `entry_price` decimal(20,8) DEFAULT NULL,
  `take_profit` decimal(20,8) DEFAULT NULL,
  `stop_loss` decimal(20,8) DEFAULT NULL,
  `confidence` decimal(5,4) DEFAULT NULL,
  `elite_score` int DEFAULT NULL,
  `trust_score` int DEFAULT NULL,
  `category` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `source_system` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT 'ACTIVE',
  `pnl_pct` decimal(10,4) DEFAULT NULL,
  `exit_price` decimal(20,8) DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `closed_at` datetime DEFAULT NULL,
  `exit_reason` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `ua_engine_stats` (
  `id` int NOT NULL AUTO_INCREMENT,
  `engine_name` varchar(50) NOT NULL,
  `asset_class` varchar(20) DEFAULT 'ALL',
  `total_predictions` int DEFAULT '0',
  `resolved` int DEFAULT '0',
  `tp_hits` int DEFAULT '0',
  `sl_hits` int DEFAULT '0',
  `expired` int DEFAULT '0',
  `win_rate` float DEFAULT '0',
  `avg_pnl` float DEFAULT '0',
  `total_pnl` float DEFAULT '0',
  `best_trade_pnl` float DEFAULT '0',
  `worst_trade_pnl` float DEFAULT '0',
  `avg_hold_hours` float DEFAULT '0',
  `sharpe_ratio` float DEFAULT '0',
  `profit_factor` float DEFAULT '0',
  `computed_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `eng_class` (`engine_name`,`asset_class`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb3;

CREATE TABLE `ua_predictions` (
  `id` int NOT NULL AUTO_INCREMENT,
  `engine_name` varchar(50) NOT NULL,
  `engine_signal_id` varchar(50) DEFAULT '',
  `asset_class` varchar(20) NOT NULL DEFAULT 'CRYPTO',
  `pair` varchar(30) NOT NULL,
  `direction` varchar(10) NOT NULL,
  `confidence` float DEFAULT '0',
  `entry_price` float DEFAULT '0',
  `tp_price` float DEFAULT '0',
  `sl_price` float DEFAULT '0',
  `tp_pct` float DEFAULT '0',
  `sl_pct` float DEFAULT '0',
  `predictability_score` float DEFAULT '0',
  `signal_time` datetime DEFAULT NULL,
  `expires_at` datetime DEFAULT NULL,
  `status` varchar(20) DEFAULT 'ACTIVE',
  `exit_price` float DEFAULT '0',
  `pnl_pct` float DEFAULT '0',
  `exit_reason` varchar(30) DEFAULT '',
  `resolved_at` datetime DEFAULT NULL,
  `hold_hours` float DEFAULT '0',
  `collected_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `engine_sig` (`engine_name`,`engine_signal_id`),
  KEY `status_idx` (`status`),
  KEY `pair_idx` (`pair`),
  KEY `engine_idx` (`engine_name`)
) ENGINE=MyISAM AUTO_INCREMENT=356 DEFAULT CHARSET=utf8mb3;

CREATE TABLE `walk_forward_results` (
  `id` int NOT NULL AUTO_INCREMENT,
  `source_table` varchar(30) NOT NULL DEFAULT 'stock_picks',
  `algorithm_name` varchar(100) NOT NULL DEFAULT '',
  `strategy_name` varchar(100) NOT NULL DEFAULT '',
  `fold_num` int NOT NULL DEFAULT '0',
  `total_folds` int NOT NULL DEFAULT '0',
  `train_start` date NOT NULL,
  `train_end` date NOT NULL,
  `test_start` date NOT NULL,
  `test_end` date NOT NULL,
  `train_picks` int NOT NULL DEFAULT '0',
  `test_picks` int NOT NULL DEFAULT '0',
  `is_best_tp` decimal(6,2) NOT NULL DEFAULT '0.00',
  `is_best_sl` decimal(6,2) NOT NULL DEFAULT '0.00',
  `is_best_hold` int NOT NULL DEFAULT '0',
  `is_win_rate` decimal(5,2) NOT NULL DEFAULT '0.00',
  `is_avg_return` decimal(10,4) NOT NULL DEFAULT '0.0000',
  `is_profit_factor` decimal(8,4) NOT NULL DEFAULT '0.0000',
  `oos_win_rate` decimal(5,2) NOT NULL DEFAULT '0.00',
  `oos_avg_return` decimal(10,4) NOT NULL DEFAULT '0.0000',
  `oos_profit_factor` decimal(8,4) NOT NULL DEFAULT '0.0000',
  `oos_trades` int NOT NULL DEFAULT '0',
  `wf_efficiency` decimal(8,4) NOT NULL DEFAULT '0.0000',
  `regime_at_test` varchar(20) NOT NULL DEFAULT '',
  `created_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_source` (`source_table`),
  KEY `idx_algo` (`algorithm_name`),
  KEY `idx_strat` (`strategy_name`),
  KEY `idx_date` (`created_at`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb3;

CREATE TABLE `walk_forward_summary` (
  `id` int NOT NULL AUTO_INCREMENT,
  `source_table` varchar(30) NOT NULL DEFAULT 'stock_picks',
  `algorithm_name` varchar(100) NOT NULL DEFAULT '',
  `strategy_name` varchar(100) NOT NULL DEFAULT '',
  `total_folds` int NOT NULL DEFAULT '0',
  `avg_wf_efficiency` decimal(8,4) NOT NULL DEFAULT '0.0000',
  `avg_oos_win_rate` decimal(5,2) NOT NULL DEFAULT '0.00',
  `avg_oos_return` decimal(10,4) NOT NULL DEFAULT '0.0000',
  `avg_is_win_rate` decimal(5,2) NOT NULL DEFAULT '0.00',
  `avg_is_return` decimal(10,4) NOT NULL DEFAULT '0.0000',
  `best_robust_tp` decimal(6,2) NOT NULL DEFAULT '0.00',
  `best_robust_sl` decimal(6,2) NOT NULL DEFAULT '0.00',
  `best_robust_hold` int NOT NULL DEFAULT '0',
  `overfitting_flag` tinyint NOT NULL DEFAULT '0',
  `naive_is_return` decimal(10,4) NOT NULL DEFAULT '0.0000',
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_src_algo` (`source_table`,`algorithm_name`,`strategy_name`)
) ENGINE=MyISAM AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb3;

CREATE TABLE `whatif_scenarios` (
  `id` int NOT NULL AUTO_INCREMENT,
  `scenario_name` varchar(200) NOT NULL DEFAULT '',
  `query_text` text,
  `params_json` text,
  `results_json` text,
  `created_at` datetime NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM AUTO_INCREMENT=115 DEFAULT CHARSET=utf8mb3;
